import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"28、【大過】 巽下兌上","description":"周易口訣義 - 28、【大過】 巽下兌上","frontmatter":{"title":"28、【大過】 巽下兌上","description":"周易口訣義 - 28、【大過】 巽下兌上"},"headers":[],"relativePath":"classics/koujueyi/030.md","filePath":"classics/koujueyi/030.md"}'),r={name:"classics/koujueyi/030.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_28、【大過】-巽下兌上" tabindex="-1">28、【大過】 巽下兌上 <a class="header-anchor" href="#_28、【大過】-巽下兌上" aria-label="Permalink to “28、【大過】 巽下兌上”">​</a></h1><p>彖曰：大過，大者過也。棟橈，本末弱也。剛過而中，巽而說行，「利有攸往」，乃亨。大過之時大矣哉！</p><p>象曰：澤滅木，大過。君子以獨立不懼，遁世無悶。</p><p>初六：藉用白茅，無咎。</p><p>象曰：「藉用白茅」，柔在下也。</p><p>九二：枯楊生稊，老夫得其女妻，無不利。</p><p>象曰：老夫女妻，過以相與也。</p><p>九三：棟橈，兇。</p><p>象曰：「棟橈」之兇，不可以有輔也。</p><p>九四，棟隆，吉。有它，吝。</p><p>象曰：「棟隆」之「吉」，不撓乎下也。</p><p>九五，枯楊生華，老婦得其士夫，無咎無譽。</p><p>象曰：「枯楊生華」，何可久也！老婦士夫，亦可醜也。</p><p>上六，過涉滅頂，兇，無咎。</p><p>象曰：「過涉」之兇，不可咎也。</p><p>解讀</p><p>「大過」者，謂過越也。衰亂之世，德大之人，過越常分，以拯患難，故曰「大過」也。「棟橈」者，棟謂屋棟也；橈，弱也，曲也。衰亂之世，始終皆弱也。「利有攸往，亨」者，謂德大之人，挺身救難，維持叔世，往必亨通。象曰「澤滅木，大過」者，「滅」，沒也；「澤」，水也，如水泛溢以至沒木，亦如小人過越常分也。「君子以獨立不懼，遁世無悶」者，此論國之大柄，故先儒於此不敢梗槩而言也。謂君子欲有救難之心，卓爾獨立，無所憂懼，不然，逃遁避世而心無憂悶也。</p><p>「初六，藉用白茅，無咎」者，以柔處下，苟能恭肅不怠，而用潔白之茅置羞於地，謹慎如此，雖遇大過之難而亦「無咎」也。</p><p>「九二：枯楊生稊，老夫得其女妻，無不利」者，以陽處陰，是拯難之人，又無偏應而無私黨，猶如枯槁之楊，更生稊穗，所益久也。衰老之夫，得其少妻，可有後嗣也。救難既多，所濟弘廣，故無所不利也。</p><p>「九三：棟橈，兇」者，以陽處陽，不能拯救危難，又應於上，有偏系之心，故棟折榱崩而致兇也。</p><p>「九四：棟隆，吉，有它吝」者，以陽處陰，猶有救難之心，故棟得隆起也；獨應於初，心不弘廣，救難褊狹，故「有它吝」。</p><p>「九五：枯楊生華，老婦得其士夫，無咎，無譽」者，以陽居陽，不能拯救衰難，以其居尊，未即橈弱，猶如枯槁之楊，雖復生華，尋見衰落，亦猶衰老之婦而得少壯之夫，即不能有益也。以其處得尊位，才得免咎而己。既不能拯捄於人，故無聲譽之美，故曰「無咎無譽」也。</p><p>上六：過涉滅頂，兇，無咎者，處「大過」之極，是救難過甚，遂「滅頂」也。為救時之苦，身至喪亡，深可哀而嗟之，又何有咎也！</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
